WATCH_INV = {"^VIX", "DX-Y.NYB", "^TNX"}


def watchlist():
    """Moje symboly: cena, denní změna a minigraf za měsíc (jako v aplikaci Akcie)."""
    try:
        data = yf.download([w[0] for w in WATCH], period="1mo", interval="1d", group_by="ticker", progress=False)
    except Exception as e:
        print("Moje symboly:", e)
        return []
    out = []
    for sym, name, short in WATCH:
        try:
            c = data[sym]["Close"].dropna()
            if len(c) < 3:
                continue
            out.append({"sym": short, "name": name, "last": float(c.iloc[-1]), "chg": float((c.iloc[-1] / c.iloc[-2] - 1) * 100),
                        "m": float((c.iloc[-1] / c.iloc[0] - 1) * 100), "sp": [round(float(x), 4) for x in c.values[-23:]], "inv": sym in WATCH_INV})
        except Exception as e:
            print("Bez dat:", sym, e)
    return out


def spark(v, up):
    if not v or len(v) < 2:
        return ""
    w, h, lo, hi = 96, 34, min(v), max(v)
    rg = (hi - lo) or 1
    pts = " ".join(f"{i * w / (len(v) - 1):.1f},{h - 3 - (x - lo) / rg * (h - 6):.1f}" for i, x in enumerate(v))
    y0 = h - 3 - (v[0] - lo) / rg * (h - 6)
    col = "var(--up)" if up else "var(--down)"
    return (f'<svg class="spark" viewBox="0 0 {w} {h}" width="{w}" height="{h}" aria-hidden="true"><line x1="0" x2="{w}" y1="{y0:.1f}" y2="{y0:.1f}" stroke="currentColor" stroke-opacity=".35" stroke-dasharray="2 3"/>'
            f'<polyline fill="none" stroke="{col}" stroke-width="1.8" stroke-linejoin="round" points="{pts}"/></svg>')


def watch_html(wl):
    if not wl:
        return ""
    rows = ""
    for r in wl:
        good = (r["chg"] <= 0) if r["inv"] else (r["chg"] >= 0)
        mgood = (r["m"] <= 0) if r["inv"] else (r["m"] >= 0)
        d = 3 if r["sym"] == "10Y" else 2
        rows += (f'<div class="wl-r"><div class="wl-n"><b>{escape(r["sym"])}</b><span>{escape(r["name"])}</span></div>{spark(r["sp"], mgood)}'
                 f'<div class="wl-p"><b>{num(r["last"], d)}</b><span class="wl-pill {"up" if good else "down"}">{pc(r["chg"])}</span></div></div>')
    return ('<section id="symboly"><h2>Moje symboly</h2><p class="hint">Jako v aplikaci Akcie: cena, změna za poslední den (barevně) a minigraf za poslední měsíc. '
            'Barva čáry ukazuje měsíc, barva rámečku poslední den. Přerušovaná čára je cena před měsícem. U VIX, dolaru a výnosů je pro akcie dobré, když klesají, proto je jejich pokles zelený.</p>'
            f'<div class="wl">{rows}</div></section>')


def nq_stats():
    """Klíčová čísla Nasdaq futures za poslední obchodní den a rok."""
    import pandas as pd
    try:
        d = yf.download("NQ=F", period="1y", interval="1d", progress=False)
        if isinstance(d.columns, pd.MultiIndex):
            d.columns = d.columns.get_level_values(0)
        d = d[["Open", "High", "Low", "Close", "Volume"]].dropna()
    except Exception as e:
        print("Čísla NQ:", e)
        return None
    if len(d) < 30:
        return None
    t, p, prev20 = d.iloc[-1], d.iloc[-2], d.iloc[-21:-1]
    rng, arng = float(t.High - t.Low), float((prev20.High - prev20.Low).mean())
    vol, avol = float(t.Volume), float(prev20.Volume.mean())
    hi, lo = float(d.High.max()), float(d.Low.min())
    return {"date": d.index[-1].strftime("%Y-%m-%d"), "last": float(t.Close), "prev": float(p.Close), "open": float(t.Open), "high": float(t.High), "low": float(t.Low),
            "rng": rng, "arng": arng, "vol": vol, "avol": avol, "hi": hi, "lo": lo, "fromhi": (float(t.Close) / hi - 1) * 100}


def nq_stats_html(x):
    if not x:
        return ""
    def big(v):
        return num(v / 1e6, 2) + NB + "mil." if v >= 1e6 else num(v / 1e3, 0) + NB + "tis."
    rr, vr = x["rng"] / x["arng"] if x["arng"] else 1, x["vol"] / x["avol"] if x["avol"] else 1
    cells = [("Otevírací cena", num(x["open"])), ("Maximum dne", num(x["high"])), ("Minimum dne", num(x["low"])),
             ("Předchozí zavření", num(x["prev"])), ("Rozsah dne", num(x["rng"], 0) + NB + "bodů"), ("Průměrný rozsah (20 dní)", num(x["arng"], 0) + NB + "bodů"),
             ("Roční maximum", num(x["hi"])), ("Roční minimum", num(x["lo"])), ("Od ročního maxima", pc(x["fromhi"])),
             ("Objem", big(x["vol"])), ("Průměrný objem (20 dní)", big(x["avol"])), ("Objem proti průměru", num(vr, 1) + "×")]
    grid = "".join(f'<div><span>{a}</span><b>{b}</b></div>' for a, b in cells)
    tips = []
    tips.append(f"Rozsah dne byl {num(rr, 1)}× průměru: " + ("trh byl živější než obvykle, stop potřebuje víc místa, nebo zmenši pozici." if rr >= 1.3
                else "trh byl klidnější než obvykle, cíle bývají menší." if rr <= 0.7 else "normální den."))
    tips.append(f"Objem byl {num(vr, 1)}× průměru: " + ("obchodovalo se hodně, pohyby jsou spolehlivější." if vr >= 1.3 else "obchodovalo se málo, pohyby bývají méně spolehlivé." if vr <= 0.7 else "běžný objem."))
    tips.append("Nasdaq je těsně u ročního maxima." if x["fromhi"] > -1.5 else f"Nasdaq je {num(abs(x['fromhi']), 1)} % pod ročním maximem.")
    dd = x["date"]
    return (f'<section><h2>Nasdaq futures v číslech</h2><p class="hint">Poslední obchodní den ({int(dd[8:])}. {int(dd[5:7])}. {dd[:4]}), jako přehled v aplikaci Akcie.</p><div class="stgrid">{grid}</div>'
            f'<ul class="facts" style="margin-top:12px">{"".join(f"<li>{escape(t)}</li>" for t in tips)}</ul>'
            '<details style="margin-top:8px"><summary>Co tato čísla znamenají</summary><ul class="facts"><li><b>Rozsah dne</b>: kolik bodů je mezi maximem a minimem dne. Podle něj odhadneš, kolik místa potřebuje stop a jak daleko může být cíl.</li>'
            '<li><b>Objem</b>: kolik kontraktů se zobchodovalo. Velký objem = pohybu věří hodně lidí.</li><li><b>Roční maximum a minimum</b>: nejvyšší a nejnižší cena za 12 měsíců. U nich trh často zpomalí nebo se otočí.</li>'
            '<li><b>Předchozí zavření</b>: cena na konci předchozího dne. Od ní se počítá denní změna v procentech.</li></ul></details></section>')


