EVENING_JS = """
(function () {
  const T = TD, key = "eve:" + T.today(); let E = T.ls(key, {}) || {};
  const HOW2PLAN = {wait: "ano", setup: "ano", castecne: "castecne", ne: "ne"};
  const how0 = E.how || (E.plan === "castecne" ? "castecne" : E.plan === "ne" ? "ne" : E.plan === "ano" ? (T.ls("pstat:" + T.today(), "") === "wait" ? "wait" : "setup") : "");
  $("e-how").value = how0; $("e-learn").value = E.learn || ""; $("e-pride").value = E.pride || 3; $("e-pv").textContent = E.pride || 3;
  const save = () => { const h = $("e-how").value; E = {how: h, plan: HOW2PLAN[h] || "", learn: $("e-learn").value, pride: +$("e-pride").value}; T.lset(key, E);
    if (h) { T.lset("pstat:" + T.today(), h === "wait" ? "wait" : h === "setup" ? "setup" : "broke"); T.lset("patience:" + T.today(), h === "wait" || h === "setup"); }
    $("e-pv").textContent = E.pride; $("e-msg").textContent = "Uloženo."; draw(); };
  ["e-how", "e-learn", "e-pride"].forEach(i => $(i).addEventListener("input", save));
  (() => { const old = []; try { for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (/^(refl|pnote):\\d{4}-\\d{2}-\\d{2}$/.test(k)) old.push(k); } } catch (e) {}
    const rows = old.map(k => { const v = T.ls(k, null); const t = typeof v === "string" ? v : v ? [v.a && "Povedlo se: " + v.a, v.b && "Příště jinak: " + v.b, v.c && "Emoce: " + v.c].filter(Boolean).join(" · ") : "";
      return t && t.trim() ? [k.slice(-10), k.startsWith("refl") ? "Mindset" : "Trpělivost", t] : null; }).filter(Boolean).sort((a, b) => b[0].localeCompare(a[0]));
    if (rows.length) $("e-old").innerHTML = `<section><details><summary><b>Starší večerní zápisy (${rows.length})</b></summary><p class="hint">Dřív se večer zapisovalo i na stránkách Mindset a Trpělivost. Teď je všechno tady, starší zápisy se neztratily.</p><div class="wrap"><table><thead><tr><th>Den</th><th>Odkud</th><th>Zápis</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${T.esc(r[2])}</td></tr>`).join("")}</tbody></table></div></details></section>`; })();
  const draw = () => { const j = T.ls("jr:day:" + T.today(), null);
    $("edn").textContent = j ? j.n + " obchodů, " + (j.net >= 0 ? "+" : "\\u2212") + Math.abs(j.net) + " $" : "Zatím bez dat";
    $("edt").textContent = j ? (j.n === 0 ? "Dnes bez obchodu. Čekání je výhra, pokud jsi nebyl u grafu s nutkáním." : "Podle plánu " + j.ano + "×, mimo plán " + j.ne + "×.") : "Otevři Deník obchodů, ať se dnešní data načtou.";
    $("me-box").innerHTML = TDme();
    const rows = []; for (let i = 0; i < 7; i++) { const d = new Date(); d.setDate(d.getDate() - i); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); const k = d.toISOString().slice(0, 10), e = T.ls("eve:" + k, null), s = TDscore(k);
      rows.push(`<tr><td>${k}</td><td>${e && e.plan ? ({ano: "Ano", castecne: "Částečně", ne: "Ne"})[e.plan] : "–"}</td><td class="n">${e && e.pride ? e.pride + " z 5" : "–"}</td><td class="n">${s == null ? "–" : s + " %"}</td></tr>`); }
    $("e-hist").innerHTML = `<div class="wrap"><table><thead><tr><th>Den</th><th>Plán</th><th class="n">Pýcha na sebe</th><th class="n">Skóre dne</th></tr></thead><tbody>${rows.join("")}</tbody></table></div>`; };
  document.addEventListener("tdday", draw); draw();
})();
"""

POST_JS = """
(function () {
  const k = "post:" + TD.today(), P = TD.ls(k, {}) || {};
  document.querySelectorAll("[data-pc]").forEach(c => { c.checked = !!P[c.dataset.pc]; c.addEventListener("change", () => { P[c.dataset.pc] = c.checked; TD.lset(k, P); }); });
})();
"""
